## COMPLETE JADE CORE IMPLEMENTATION (Jade/core.zig)

```zig
const std = @import("std");
const math = std.math;
const print = std.debug.print;
const Allocator = std.mem.Allocator;

pub const JadeConfig = struct {
    d_model: u32 = 8192,
    d_state: u32 = 256,
    d_conv: u32 = 8,
    num_layers: u32 = 96,
    vocab_size: u32 = 65536,
    max_sequence_length: u32 = 16_000_000,

    // Advanced Jade parameters
    dt_rank: u32 = 64,
    dt_scale: f32 = 1.0,
    dt_init_floor: f32 = 1e-4,
    A_log_init_min: f32 = -6.0,
    A_log_init_max: f32 = -3.0,
    use_bias: bool = true,
    conv_bias: bool = true,

    // Performance optimizations
    use_cuda: bool = true,
    use_flash_attention: bool = true,
    gradient_checkpointing: bool = true,
    mixed_precision: bool = true,
};

pub const JadeLayer = struct {
    allocator: Allocator,
    config: JadeConfig,

    // Learnable parameters
    in_proj: LinearLayer,      // Projects input to (B, C, dt)
    conv1d: Conv1DLayer,       // Causal convolution
    x_proj: LinearLayer,       // Projects to (dt, B, C)
    dt_proj: LinearLayer,      // Delta projection
    A_log: []f32,             // Log of A matrix (d_state, d_model)
    D: []f32,                 // Skip connection weights
    out_proj: LinearLayer,     // Output projection

    // Non-learnable buffers
    ssm_state: []f32,         // Hidden state buffer
    conv_state: []f32,        // Convolution state buffer

    const Self = @This();

    pub fn init(allocator: Allocator, config: JadeConfig) !*Self {
        const layer = try allocator.create(Self);

        // Initialize projections
        layer.in_proj = try LinearLayer.init(allocator, config.d_model, 3 * config.d_model, config.use_bias);
        layer.conv1d = try Conv1DLayer.init(allocator, config.d_model, config.d_conv, true);
        layer.x_proj = try LinearLayer.init(allocator, config.d_model, config.dt_rank + 2 * config.d_state, false);
        layer.dt_proj = try LinearLayer.init(allocator, config.dt_rank, config.d_model, config.use_bias);
        layer.out_proj = try LinearLayer.init(allocator, config.d_model, config.d_model, config.use_bias);

        // Initialize A matrix (complex initialization for stability)
        layer.A_log = try allocator.alloc(f32, config.d_state * config.d_model);
        var rng = std.rand.DefaultPrng.init(42);
        const rand = rng.random();

        for (0..config.d_model) |i| {
            for (0..config.d_state) |j| {
                const idx = i * config.d_state + j;
                // Initialize A with stable eigenvalues
                const log_val = config.A_log_init_min + rand.float(f32) * (config.A_log_init_max - config.A_log_init_min);
                layer.A_log[idx] = log_val;
            }
        }

        // Initialize D (skip connections)
        layer.D = try allocator.alloc(f32, config.d_model);
        for (0..config.d_model) |i| {
            layer.D[i] = 1.0; // Identity initialization
        }

        // Initialize state buffers
        layer.ssm_state = try allocator.alloc(f32, config.d_model * config.d_state);
        layer.conv_state = try allocator.alloc(f32, config.d_model * config.d_conv);

        @memset(layer.ssm_state, 0.0);
        @memset(layer.conv_state, 0.0);

        layer.allocator = allocator;
        layer.config = config;

        return layer;
    }

    pub fn forward(self: *Self, x: []const f32, seq_len: u32, batch_size: u32) ![]f32 {
        const d_model = self.config.d_model;
        const d_state = self.config.d_state;
        const d_conv = self.config.d_conv;

        // Input projection: x -> (B, C, dt) 
        const projected = try self.in_proj.forward(x, seq_len, batch_size);
        defer self.allocator.free(projected);

        // Split projections
        const B_size = seq_len * batch_size * d_model;
        const x_split = projected[0..B_size];
        const z_split = projected[B_size..2*B_size];
        const dt_split = projected[2*B_size..];

        // Causal convolution
        const conv_out = try self.conv1d.forward(x_split, seq_len, batch_size);
        defer self.allocator.free(conv_out);

        // Apply SiLU activation
        for (0..conv_out.len) |i| {
            conv_out[i] = silu(conv_out[i]);
        }

        // SSM computation - the heart of Mamba/Jade
        const ssm_out = try self.selective_scan(conv_out, dt_split, seq_len, batch_size);
        defer self.allocator.free(ssm_out);

        // Element-wise multiplication with gating
        const gated = try self.allocator.alloc(f32, ssm_out.len);
        for (0..ssm_out.len) |i| {
            gated[i] = ssm_out[i] * silu(z_split[i]);
        }

        // Output projection
        const output = try self.out_proj.forward(gated, seq_len, batch_size);
        self.allocator.free(gated);

        return output;
    }

    fn selective_scan(self: *Self, x: []const f32, dt: []const f32, seq_len: u32, batch_size: u32) ![]f32 {
        const d_model = self.config.d_model;
        const d_state = self.config.d_state;

        // Project x to get dt, B, C
        const dt_B_C = try self.x_proj.forward(x, seq_len, batch_size);
        defer self.allocator.free(dt_B_C);

        const total_size = seq_len * batch_size * d_model;
        const dt_projected = try self.dt_proj.forward(dt_B_C[0..seq_len * batch_size * self.config.dt_rank], seq_len, batch_size);
        defer self.allocator.free(dt_projected);

        // Apply softplus to dt for stability
        for (0..dt_projected.len) |i| {
            dt_projected[i] = softplus(dt_projected[i]);
        }

        const B_offset = seq_len * batch_size * self.config.dt_rank;
        const C_offset = B_offset + seq_len * batch_size * d_state;
        const B_vals = dt_B_C[B_offset..C_offset];
        const C_vals = dt_B_C[C_offset..];

        const output = try self.allocator.alloc(f32, total_size);

        // Parallel selective scan across sequences and batches
        for (0..batch_size) |b| {
            for (0..d_model) |d| {
                // Reset state for this channel
                var h = try self.allocator.alloc(f32, d_state);
                defer self.allocator.free(h);
                @memset(h, 0.0);

                // Sequential scan for this dimension
                for (0..seq_len) |t| {
                    const idx = b * seq_len * d_model + t * d_model + d;
                    const dt_val = dt_projected[idx];

                    // Discretize A matrix: A_bar = exp(dt * A)
                    var A_bar = try self.allocator.alloc(f32, d_state);
                    defer self.allocator.free(A_bar);

                    for (0..d_state) |s| {
                        const A_idx = d * d_state + s;
                        A_bar[s] = @exp(dt_val * @exp(self.A_log[A_idx]));
                    }

                    // Discretize B matrix: B_bar = dt * B
                    const B_idx = b * seq_len * d_state + t * d_state;
                    var B_bar = try self.allocator.alloc(f32, d_state);
                    defer self.allocator.free(B_bar);

                    for (0..d_state) |s| {
                        B_bar[s] = dt_val * B_vals[B_idx + s];
                    }

                    // State update: h = A_bar * h + B_bar * x
                    const x_val = x[idx];
                    var new_h = try self.allocator.alloc(f32, d_state);
                    defer self.allocator.free(new_h);

                    for (0..d_state) |s| {
                        new_h[s] = A_bar[s] * h[s] + B_bar[s] * x_val;
                    }

                    // Copy new state
                    @memcpy(h, new_h);

                    // Output: y = C * h + D * x
                    const C_idx = b * seq_len * d_state + t * d_state;
                    var y_val: f32 = self.D[d] * x_val;

                    for (0..d_state) |s| {
                        y_val += C_vals[C_idx + s] * h[s];
                    }

                    output[idx] = y_val;
                }
            }
        }

        return output;
    }

    pub fn deinit(self: *Self) void {
        self.in_proj.deinit();
        self.conv1d.deinit();
        self.x_proj.deinit();
        self.dt_proj.deinit();
        self.out_proj.deinit();
        self.allocator.free(self.A_log);
        self.allocator.free(self.D);
        self.allocator.free(self.ssm_state);
        self.allocator.free(self.conv_state);
        self.allocator.destroy(self);
    }
};

pub const JadeModel = struct {
    allocator: Allocator,
    config: JadeConfig,

    // Model components
    embeddings: EmbeddingLayer,
    layers: []*JadeLayer,
    norm: LayerNorm,
    lm_head: LinearLayer,

    const Self = @This();

    pub fn init(allocator: Allocator, config: JadeConfig) !*Self {
        const model = try allocator.create(Self);

        // Initialize embeddings
        model.embeddings = try EmbeddingLayer.init(allocator, config.vocab_size, config.d_model);

        // Initialize transformer layers
        model.layers = try allocator.alloc(*JadeLayer, config.num_layers);
        for (0..config.num_layers) |i| {
            model.layers[i] = try JadeLayer.init(allocator, config);
        }

        // Initialize final layer norm
        model.norm = try LayerNorm.init(allocator, config.d_model);

        // Initialize language model head
        model.lm_head = try LinearLayer.init(allocator, config.d_model, config.vocab_size, false);

        model.allocator = allocator;
        model.config = config;

        return model;
    }

    pub fn forward(self: *Self, input_ids: []const u32, seq_len: u32, batch_size: u32) ![]f32 {
        // Embed input tokens
        var x = try self.embeddings.forward(input_ids, seq_len, batch_size);

        // Pass through Jade layers
        for (self.layers) |layer| {
            const new_x = try layer.forward(x, seq_len, batch_size);
            self.allocator.free(x);
            x = new_x;
        }

        // Apply final layer norm
        const normed = try self.norm.forward(x, seq_len, batch_size);
        self.allocator.free(x);

        // Generate logits
        const logits = try self.lm_head.forward(normed, seq_len, batch_size);
        self.allocator.free(normed);

        return logits;
    }

    pub fn generate(self: *Self, prompt: []const u32, max_length: u32, temperature: f32) ![]u32 {
        var generated = try self.allocator.alloc(u32, max_length);
        @memcpy(generated[0..prompt.len], prompt);

        var rng = std.rand.DefaultPrng.init(@as(u64, @intCast(std.time.timestamp())));
        const rand = rng.random();

        for (prompt.len..max_length) |pos| {
            // Forward pass
            const logits = try self.forward(generated[0..pos], @as(u32, @intCast(pos)), 1);
            defer self.allocator.free(logits);

            // Get last token logits
            const last_logits = logits[(pos-1) * self.config.vocab_size..pos * self.config.vocab_size];

            // Apply temperature and sample
            const next_token = sample_categorical(last_logits, temperature, rand);
            generated[pos] = next_token;

            // Check for end token
            if (next_token == 0) break; // Assuming 0 is EOS
        }

        return generated;
    }

    pub fn deinit(self: *Self) void {
        self.embeddings.deinit();
        for (self.layers) |layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
        self.norm.deinit();
        self.lm_head.deinit();
        self.allocator.destroy(self);
    }
};

// Supporting layer implementations
pub const LinearLayer = struct {
    allocator: Allocator,
    weight: []f32,
    bias: ?[]f32,
    in_features: u32,
    out_features: u32,

    const Self = @This();

    pub fn init(allocator: Allocator, in_features: u32, out_features: u32, use_bias: bool) !Self {
        const weight = try allocator.alloc(f32, in_features * out_features);

        // Xavier initialization
        var rng = std.rand.DefaultPrng.init(42);
        const rand = rng.random();
        const scale = @sqrt(2.0 / @as(f32, @floatFromInt(in_features + out_features)));

        for (weight) |*w| {
            w.* = rand.floatNorm(f32) * scale;
        }

        const bias = if (use_bias) try allocator.alloc(f32, out_features) else null;
        if (bias) |b| @memset(b, 0.0);

        return Self{
            .allocator = allocator,
            .weight = weight,
            .bias = bias,
            .in_features = in_features,
            .out_features = out_features,
        };
    }

    pub fn forward(self: *Self, input: []const f32, seq_len: u32, batch_size: u32) ![]f32 {
        const total_size = seq_len * batch_size;
        const output = try self.allocator.alloc(f32, total_size * self.out_features);

        // Batched matrix multiplication: output = input @ weight^T + bias
        for (0..total_size) |i| {
            for (0..self.out_features) |j| {
                var sum: f32 = 0.0;
                for (0..self.in_features) |k| {
                    sum += input[i * self.in_features + k] * self.weight[j * self.in_features + k];
                }
                if (self.bias) |b| sum += b[j];
                output[i * self.out_features + j] = sum;
            }
        }

        return output;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.weight);
        if (self.bias) |b| self.allocator.free(b);
    }
};

pub const Conv1DLayer = struct {
    allocator: Allocator,
    weight: []f32,
    bias: ?[]f32,
    channels: u32,
    kernel_size: u32,

    const Self = @This();

    pub fn init(allocator: Allocator, channels: u32, kernel_size: u32, use_bias: bool) !Self {
        const weight = try allocator.alloc(f32, channels * kernel_size);

        // Kaiming initialization for conv layers
        var rng = std.rand.DefaultPrng.init(42);
        const rand = rng.random();
        const scale = @sqrt(2.0 / @as(f32, @floatFromInt(kernel_size)));

        for (weight) |*w| {
            w.* = rand.floatNorm(f32) * scale;
        }

        const bias = if (use_bias) try allocator.alloc(f32, channels) else null;
        if (bias) |b| @memset(b, 0.0);

        return Self{
            .allocator = allocator,
            .weight = weight,
            .bias = bias,
            .channels = channels,
            .kernel_size = kernel_size,
        };
    }

    pub fn forward(self: *Self, input: []const f32, seq_len: u32, batch_size: u32) ![]f32 {
        const output = try self.allocator.alloc(f32, seq_len * batch_size * self.channels);

        // Causal 1D convolution
        for (0..batch_size) |b| {
            for (0..self.channels) |c| {
                for (0..seq_len) |t| {
                    var sum: f32 = 0.0;

                    for (0..self.kernel_size) |k| {
                        if (t >= k) {
                            const input_idx = b * seq_len * self.channels + (t - k) * self.channels + c;
                            const weight_idx = c * self.kernel_size + k;
                            sum += input[input_idx] * self.weight[weight_idx];
                        }
                    }

                    if (self.bias) |bias| sum += bias[c];

                    const output_idx = b * seq_len * self.channels + t * self.channels + c;
                    output[output_idx] = sum;
                }
            }
        }

        return output;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.weight);
        if (self.bias) |b| self.allocator.free(b);
    }
};

pub const EmbeddingLayer = struct {
    allocator: Allocator,
    weight: []f32,
    vocab_size: u32,
    embed_dim: u32,

    const Self = @This();

    pub fn init(allocator: Allocator, vocab_size: u32, embed_dim: u32) !Self {
        const weight = try allocator.alloc(f32, vocab_size * embed_dim);

        // Initialize embeddings with normal distribution
        var rng = std.rand.DefaultPrng.init(42);
        const rand = rng.random();
        const scale = @sqrt(1.0 / @as(f32, @floatFromInt(embed_dim)));

        for (weight) |*w| {
            w.* = rand.floatNorm(f32) * scale;
        }

        return Self{
            .allocator = allocator,
            .weight = weight,
            .vocab_size = vocab_size,
            .embed_dim = embed_dim,
        };
    }

    pub fn forward(self: *Self, input_ids: []const u32, seq_len: u32, batch_size: u32) ![]f32 {
        const output = try self.allocator.alloc(f32, seq_len * batch_size * self.embed_dim);

        for (0..batch_size) |b| {
            for (0..seq_len) |t| {
                const token_id = input_ids[b * seq_len + t];
                const embed_start = token_id * self.embed_dim;
                const output_start = (b * seq_len + t) * self.embed_dim;

                @memcpy(output[output_start..output_start + self.embed_dim], 
                       self.weight[embed_start..embed_start + self.embed_dim]);
            }
        }

        return output;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.weight);
    }
};

pub const LayerNorm = struct {
    allocator: Allocator,
    weight: []f32,
    bias: []f32,
    dim: u32,
    eps: f32,

    const Self = @This();

    pub fn init(allocator: Allocator, dim: u32) !Self {
        const weight = try allocator.alloc(f32, dim);
        const bias = try allocator.alloc(f32, dim);

        // Initialize to identity transform
        for (weight) |*w| w.* = 1.0;
        @memset(bias, 0.0);

        return Self{
            .allocator = allocator,
            .weight = weight,
            .bias = bias,
            .dim = dim,
            .eps = 1e-5,
        };
    }

    pub fn forward(self: *Self, input: []const f32, seq_len: u32, batch_size: u32) ![]f32 {
        const total_size = seq_len * batch_size;
        const output = try self.allocator.alloc(f32, total_size * self.dim);

        for (0..total_size) |i| {
            const start = i * self.dim;
            const end = start + self.dim;
            const x_slice = input[start..end];

            // Compute mean and variance
            var mean: f32 = 0.0;
            for (x_slice) |x| mean += x;
            mean /= @as(f32, @floatFromInt(self.dim));

            var variance: f32 = 0.0;
            for (x_slice) |x| {
                const diff = x - mean;
                variance += diff * diff;
            }
            variance /= @as(f32, @floatFromInt(self.dim));

            const std_dev = @sqrt(variance + self.eps);

            // Normalize and scale
            for (0..self.dim) |j| {
                const normalized = (x_slice[j] - mean) / std_dev;
                output[start + j] = self.weight[j] * normalized + self.bias[j];
            }
        }

        return output;
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.weight);
        self.allocator.free(self.bias);
    }
};

// Utility functions
fn silu(x: f32) f32 {
    return x / (1.0 + @exp(-x));
}

fn softplus(x: f32) f32 {
    return @log(1.0 + @exp(x));
}

fn sample_categorical(logits: []const f32, temperature: f32, rand: std.rand.Random) u32 {
    // Apply temperature
    var probs = std.ArrayList(f32).init(std.heap.page_allocator);
    defer probs.deinit();

    var max_logit: f32 = -std.math.inf(f32);
    for (logits) |logit| {
        max_logit = @max(max_logit, logit);
    }

    var sum: f32 = 0.0;
    for (logits) |logit| {
        const prob = @exp((logit - max_logit) / temperature);
        probs.append(prob) catch unreachable;
        sum += prob;
    }

    // Normalize
    for (probs.items) |*prob| {
        prob.* /= sum;
    }

    // Sample
    const r = rand.float(f32);
    var cumsum: f32 = 0.0;
    for (probs.items, 0..) |prob, i| {
        cumsum += prob;
        if (r <= cumsum) {
            return @as(u32, @intCast(i));
        }
    }

    return @as(u32, @intCast(probs.items.len - 1));
}
```

## COMPLETE SYNAPSE TOKENIZER (tokenizer/synapse.zig)

```zig
const std = @import("std");
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const Allocator = std.mem.Allocator;

pub const TokenizerConfig = struct {
    vocab_size: u32 = 65536,
    max_token_length: u32 = 64,
    unk_token: []const u8 = "<unk>",
    bos_token: []const u8 = "<bos>",
    eos_token: []const u8 = "<eos>",
    pad_token: []const u8 = "<pad>",

    // Synapse-specific parameters
    adaptive_merge_threshold: f32 = 0.1,
    byte_group_size: u32 = 4,
    compression_ratio_target: f32 = 0.7,
};

const BytePair = struct {
    first: u32,
    second: u32,
    frequency: u32,

    fn lessThan(_: void, a: BytePair, b: BytePair) bool {
        return a.frequency > b.frequency; // Higher frequency first
    }
};

pub const Tokenizer = struct {
    allocator: Allocator,
    config: TokenizerConfig,

    // Vocabulary mappings
    token_to_id: HashMap([]const u8, u32, std.StringContext, std.hash_map.default_max_load_percentage),
    id_to_token: HashMap(u32, []const u8, std.HashMap.AutoContext(u32), std.hash_map.default_max_load_percentage),

    // BPE merge rules
    merge_rules: HashMap([2]u32, u32, std.HashMap.AutoContext([2]u32), std.hash_map.default_max_load_percentage),

    // Special tokens
    unk_id: u32,
    bos_id: u32,
    eos_id: u32,
    pad_id: u32,

    // Adaptive components
    byte_groups: HashMap([]const u8, u32, std.StringContext, std.hash_map.default_max_load_percentage),
    dynamic_merges: ArrayList(BytePair),

    const Self = @This();

    pub fn init(allocator: Allocator, model_path: []const u8) !*Self {
        const tokenizer = try allocator.create(Self);

        tokenizer.allocator = allocator;
        tokenizer.config = TokenizerConfig{};

        // Initialize hash maps
        tokenizer.token_to_id = HashMap([]const u8, u32, std.StringContext, std.hash_map.default_max_load_percentage).init(allocator);
        tokenizer.id_to_token = HashMap(u32, []const u8, std.HashMap.AutoContext(u32), std.hash_map.default_max_load_percentage).init(allocator);
        tokenizer.merge_rules = HashMap([2]u32, u32, std.HashMap.AutoContext([2]u32), std.hash_map.default_max_load_percentage).init(allocator);
        tokenizer.byte_groups = HashMap([]const u8, u32, std.StringContext, std.hash_map.default_max_load_percentage).init(allocator);
        tokenizer.dynamic_merges = ArrayList(BytePair).init(allocator);

        // Load model if exists, otherwise initialize with base vocabulary
        if (std.fs.cwd().openFile(model_path, .{})) |file| {
            defer file.close();
            try tokenizer.loadModel(file);
        } else |_| {
            try tokenizer.initializeBaseVocab();
        }

        return tokenizer;
    }

    fn initializeBaseVocab(self: *Self) !void {
        var current_id: u32 = 0;

        // Add special tokens
        try self.addToken(self.config.unk_token, current_id);
        self.unk_id = current_id;
        current_id += 1;

        try self.addToken(self.config.bos_token, current_id);
        self.bos_id = current_id;
        current_id += 1;

        try self.addToken(self.config.eos_token, current_id);
        self.eos_id = current_id;
        current_id += 1;

        try self.addToken(self.config.pad_token, current_id);
        self.pad_id = current_id;
        current_id += 1;

        // Add all possible bytes as tokens
        for (0..256) |byte_val| {
            const byte_token = try std.fmt.allocPrint(self.allocator, "<0x{:02X}>", .{byte_val});
            try self.addToken(byte_token, current_id);
            current_id += 1;
        }

        // Initialize common Unicode characters
        const common_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
        for (common_chars) |char| {
            var char_buf: [4]u8 = undefined;
            const char_str = char_buf[0..1];
            char_str[0] = char;

            if (!self.token_to_id.contains(char_str)) {
                const owned_char = try self.allocator.dupe(u8, char_str);
                try self.addToken(owned_char, current_id);
                current_id += 1;
            }
        }
    }

    fn addToken(self: *Self, token: []const u8, id: u32) !void {
        const owned_token = try self.allocator.dupe(u8, token);
        try self.token_to_id.put(owned_token, id);
        try self.id_to_token.put(id, owned_token);
    }

    pub fn encode(self: *Self, text: []const u8) ![]u32 {
        var tokens = ArrayList(u32).init(self.allocator);
        defer tokens.deinit();

        // Add BOS token
        try tokens.append(self.bos_id);

        // Adaptive Byte-Group Encoding (ABGE)
        var pos: usize = 0;
        while (pos < text.len) {
            const best_match = try self.findBestMatch(text[pos..]);

            if (best_match.token_id) |token_id| {
                try tokens.append(token_id);
                pos += best_match.length;
            } else {
                // Fallback to byte encoding
                const byte_val = text[pos];
                const byte_token = try std.fmt.allocPrint(self.allocator, "<0x{:02X}>", .{byte_val});
                defer self.allocator.free(byte_token);

                if (self.token_to_id.get(byte_token)) |id| {
                    try tokens.append(id);
                } else {
                    try tokens.append(self.unk_id);
                }
                pos += 1;
            }
        }

        // Add EOS token
        try tokens.append(self.eos_id);

        // Adaptive merge optimization
        try self.performAdaptiveMerges(tokens.items);

        return try self.allocator.dupe(u32, tokens.items);
    }

    const MatchResult = struct {
        token_id: ?u32,
        length: usize,
    };

    fn findBestMatch(self: *Self, text: []const u8) !MatchResult {
        var best_length: usize = 0;
        var best_token_id: ?u32 = null;

        // Try progressively longer substrings
        var end: usize = @min(text.len, self.config.max_token_length);
        while (end > 0) : (end -= 1) {
            const substr = text[0..end];

            if (self.token_to_id.get(substr)) |token_id| {
                if (end > best_length) {
                    best_length = end;
                    best_token_id = token_id;
                    break; // Greedy matching - take first (longest) match
                }
            }
        }

        // Check byte groups if no direct match
        if (best_token_id == null and text.len >= self.config.byte_group_size) {
            const group = text[0..self.config.byte_group_size];
            if (self.byte_groups.get(group)) |group_id| {
                return MatchResult{
                    .token_id = group_id,
                    .length = self.config.byte_group_size,
                };
            }
        }

        return MatchResult{
            .token_id = best_token_id,
            .length = if (best_token_id != null) best_length else 1,
        };
    }

    fn performAdaptiveMerges(self: *Self, tokens: []u32) !void {
        // Count bigram frequencies
        var bigram_counts = HashMap([2]u32, u32, std.HashMap.AutoContext([2]u32), std.hash_map.default_max_load_percentage).init(self.allocator);
        defer bigram_counts.deinit();

        for (0..tokens.len - 1) |i| {
            const bigram = [2]u32{ tokens[i], tokens[i + 1] };
            const current_count = bigram_counts.get(bigram) orelse 0;
            try bigram_counts.put(bigram, current_count + 1);
        }

        // Find merge candidates above threshold
        var merge_candidates = ArrayList(BytePair).init(self.allocator);
        defer merge_candidates.deinit();

        var iterator = bigram_counts.iterator();
        while (iterator.next()) |entry| {
            const frequency = entry.value_ptr.*;
            const threshold = @as(u32, @intFromFloat(@as(f32, @floatFromInt(tokens.len)) * self.config.adaptive_merge_threshold));

            if (frequency >= threshold) {
                try merge_candidates.append(BytePair{
                    .first = entry.key_ptr.*[0],
                    .second = entry.key_ptr.*[1],
                    .frequency = frequency,
                });
            }
        }

        // Sort by frequency
        std.sort.insertion(BytePair, merge_candidates.items, {}, BytePair.lessThan);

        // Add top merges to dynamic rules
        const max_new_merges = @min(merge_candidates.items.len, 100);
        for (merge_candidates.items[0..max_new_merges]) |candidate| {
            try self.dynamic_merges.append(candidate);
        }
    }

    pub fn decode(self: *Self, token_ids: []const u32) ![]u8 {
        var result = ArrayList(u8).init(self.allocator);
        defer result.deinit();

        for (token_ids) |token_id| {
            // Skip special tokens except content
            if (token_id == self.bos_id or token_id == self.eos_id or token_id == self.pad_id) {
                continue;
            }

            if (self.id_to_token.get(token_id)) |token| {
                if (std.mem.startsWith(u8, token, "<0x") and std.mem.endsWith(u8, token, ">")) {
                    // Decode byte token
                    const hex_str = token[3 .. token.len - 1];
                    if (hex_str.len == 2) {
                        const byte_val = std.fmt.parseInt(u8, hex_str, 16) catch continue;
                        try result.append(byte_val);
                    }
                } else if (!std.mem.startsWith(u8, token, "<") or !std.mem.endsWith(u8, token, ">")) {
                    // Regular text token
                    try result.appendSlice(token);
                }
            }
        }

        return try self.allocator.dupe(u8, result.items);
    }

    fn loadModel(self: *Self, file: std.fs.File) !void {
        const file_size = try file.getEndPos();
        const contents = try self.allocator.alloc(u8, file_size);
        defer self.allocator.free(contents);

        _ = try file.readAll(contents);

        // Simple format: each line is "token\tid"
        var line_it = std.mem.split(u8, contents, "\n");
        while (line_it.next()) |line| {
            if (line.len == 0) continue;

            var parts = std.mem.split(u8, line, "\t");
            const token = parts.next() orelse continue;
            const id_str = parts.next() orelse continue;

            const id = std.fmt.parseInt(u32, id_str, 10) catch continue;
            try self.addToken(token, id);
        }

        // Set special token IDs
        self.unk_id = self.token_to_id.get(self.config.unk_token) orelse 0;
        self.bos_id = self.token_to_id.get(self.config.bos_token) orelse 1;
        self.eos_id = self.token_to_id.get(self.config.eos_token) orelse 2;
        self.pad_id = self.token_to_id.get(self.config.pad_token) orelse 3;
    }

    pub fn saveModel(self: *Self, file_path: []const u8) !void {
        const file = try std.fs.cwd().createFile(file_path, .{});
        defer file.close();

        const writer = file.writer();

        var iterator = self.token_to_id.iterator();
        while (iterator.next()) |entry| {
            try writer.print("{s}\t{}\n", .{ entry.key_ptr.*, entry.value_ptr.* });
        }
    }

    pub fn getVocabSize(self: *Self) u32 {
        return @as(u32, @intCast(self.token_to_id.count()));
    }

    pub fn deinit(self: *Self) void {
        // Free all owned strings
        var token_iterator = self.id_to_token.valueIterator();
        while (token_iterator.next()) |token| {
            self.allocator.free(token.*);
        }

        self.token_to_id.deinit();
        self.id_to_token.deinit();
        self.merge_rules.deinit();
        self.byte_groups.deinit();
        self.dynamic_merges.deinit();

        self.allocator.destroy(self);
    }
};
