    .rst_n(rst_n),
    .wr_en(input_fifo_wr_en),
    .rd_en(input_fifo_rd_en),
    .din(rdata[DATA_WIDTH-1:0]), // Extract from 512-bit bus
    .dout(input_fifo_data),
    .full(input_fifo_full),
    .empty(input_fifo_empty)
);

fifo_sync #(
    .DATA_WIDTH(DATA_WIDTH),
    .FIFO_DEPTH(FIFO_DEPTH)
) output_fifo (
    .clk(clk),
    .rst_n(rst_n),
    .wr_en(output_fifo_wr_en),
    .rd_en(output_fifo_rd_en),
    .din(pe_output[pe_counter % NUM_PE]),
    .dout(output_fifo_data),
    .full(output_fifo_full),
    .empty(output_fifo_empty)
);

// ============================================================================
// Memory Interface Controller
// ============================================================================

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        araddr <= 0;
        arlen <= 0;
        arsize <= 3'b010; // 4 bytes
        arvalid <= 0;
        rready <= 0;

        awaddr <= 0;
        awlen <= 0;
        awsize <= 3'b010;
        awvalid <= 0;
        wdata <= 0;
        wstrb <= 0;
        wlast <= 0;
        wvalid <= 0;
        bready <= 1;

    end else begin
        case (current_state)
            LOAD_PARAMS: begin
                if (!arvalid) begin
                    araddr <= 32'h1000_0000; // Parameter memory base
                    arlen <= 255; // Burst of 256 transfers
                    arvalid <= 1;
                    rready <= 1;
                end else if (arready) begin
                    arvalid <= 0;
                end
            end

            FETCH_DATA: begin
                input_fifo_wr_en <= rvalid && !input_fifo_full;
                if (rlast) begin
                    rready <= 0;
                end
            end

            WRITEBACK: begin
                if (!awvalid && !output_fifo_empty) begin
                    awaddr <= 32'h2000_0000; // Output memory base  
                    awlen <= 63; // Burst write
                    awvalid <= 1;
                    wvalid <= 1;
                    wdata[DATA_WIDTH-1:0] <= output_fifo_data;
                    wstrb <= 64'hFFFF_FFFF_FFFF_FFFF;
                    output_fifo_rd_en <= 1;
                end else if (awready) begin
                    awvalid <= 0;
                end

                if (wready && wvalid) begin
                    wlast <= (pe_counter >= NUM_PE - 1);
                    if (wlast) begin
                        wvalid <= 0;
                    end
                end
            end

            default: begin
                input_fifo_wr_en <= 0;
                output_fifo_rd_en <= 0;
            end
        endcase
    end
end

// ============================================================================
// Control and Status
// ============================================================================

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done <= 0;
        error <= 0;
        pe_counter <= 0;
        cycle_counter <= 0;
        total_cycles <= 0;
        cache_addr <= 0;
    end else begin
        cycle_counter <= cycle_counter + 1;

        case (current_state)
            IDLE: begin
                done <= 0;
                pe_counter <= 0;
            end

            COMPUTE: begin
                if (pipe_valid[0]) begin
                    pe_counter <= pe_counter + 1;
                    cache_addr <= cache_addr + 4;
                end
            end

            WRITEBACK: begin
                if (wlast && wvalid && wready) begin
                    done <= 1;
                    total_cycles <= total_cycles + cycle_counter;
                end
            end

            ERROR_STATE: begin
                error <= 1;
                error_code <= 16'hDEAD;
            end
        endcase
    end
end

// Performance monitoring outputs
assign cycle_count = total_cycles;
assign status_reg = {16'h0, error_code};
assign throughput_mbps = (data_transferred * 1000) / (cycle_counter + 1);
assign utilization_pct = (active_cycles * 100) / (cycle_counter + 1);

// ============================================================================
// FIFO Implementation Module
// ============================================================================

module fifo_sync #(
    parameter DATA_WIDTH = 16,
    parameter FIFO_DEPTH = 1024
)(
    input  wire clk,
    input  wire rst_n,
    input  wire wr_en,
    input  wire rd_en,
    input  wire [DATA_WIDTH-1:0] din,
    output reg  [DATA_WIDTH-1:0] dout,
    output wire full,
    output wire empty
);

    localparam ADDR_WIDTH = $clog2(FIFO_DEPTH);

    reg [DATA_WIDTH-1:0] memory [0:FIFO_DEPTH-1];
    reg [ADDR_WIDTH:0] wr_ptr, rd_ptr;

    wire [ADDR_WIDTH-1:0] wr_addr = wr_ptr[ADDR_WIDTH-1:0];
    wire [ADDR_WIDTH-1:0] rd_addr = rd_ptr[ADDR_WIDTH-1:0];

    assign full = (wr_ptr[ADDR_WIDTH] != rd_ptr[ADDR_WIDTH]) && 
                  (wr_addr == rd_addr);
    assign empty = (wr_ptr == rd_ptr);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            dout <= 0;
        end else begin
            if (wr_en && !full) begin
                memory[wr_addr] <= din;
                wr_ptr <= wr_ptr + 1;
            end

            if (rd_en && !empty) begin
                dout <= memory[rd_addr];
                rd_ptr <= rd_ptr + 1;
            end
        end
    end
endmodule

