    %d_model_ptr = getelementptr inbounds %struct.JadeParams, %struct.JadeParams* %params, i64 0, i32 0
    %d_model = load i32, i32* %d_model_ptr, align 4, !range !{i32 1, i32 65536}
    %d_state_ptr = getelementptr inbounds %struct.JadeParams, %struct.JadeParams* %params, i64 0, i32 1  
    %d_state = load i32, i32* %d_state_ptr, align 4, !range !{i32 1, i32 1024}

