    %vector_width = 16
    %d_model_vec_chunks = udiv i64 %d_model_64, %vector_width
    %d_state_vec_chunks = udiv i64 %d_state_64, %vector_width

    ; Branch to vectorized or scalar epilogue based on alignment
    %d_model_remainder = urem i64 %d_model_64, %vector_width
    %use_full_vectors = icmp eq i64 %d_model_remainder, 0
